import math

def inv(a, m):
	m0 = m
	x0 = 0
	x1 = 1
	if m == 1:
		return 0
	while a > 1:
		if m == 0:
			return -1
		q = a // m
		t = m
		m = a % m
		a = t
		t = x0
		x0 = x1 - q * x0
		x1 = t
	if x1 < 0:
		x1 = x1 + m0
	return x1

def CRT(num, rem):
	k = 2
	prod = 1
	for i in range(0, k):
		prod = prod * num[i]
	result = 0
	for i in range(0, k):
		pp = prod // num[i]
		is_zero = inv(pp, num[i])
		if is_zero == -1:
			return -1
		result = result + rem[i] * inv(pp, num[i]) * pp
	return result % prod

def gcdExtended(a, b):
	if a == 0:
		return (b, 0, 1)
	(gcd, x1, y1) = gcdExtended(b % a, a)
	x = y1 - b // a * x1
	y = x1
	return (gcd, x, y)

